SELECT json_build_object('checks',(SELECT json_agg(x) FROM (SELECT 'public.'||c.relname AS relation,k.conname,pg_get_expr(k.conbin,k.conrelid,false) AS expression FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid WHERE c.relnamespace=pg_my_temp_schema() AND k.contype='c' ORDER BY c.relname,k.conname LIMIT 81) x),'defaults',(SELECT json_agg(x) FROM (SELECT 'public.'||c.relname AS relation,a.attname,pg_get_expr(d.adbin,d.adrelid,false) AS expression FROM pg_attrdef d JOIN pg_attribute a ON a.attrelid=d.adrelid AND a.attnum=d.adnum JOIN pg_class c ON c.oid=d.adrelid WHERE c.relnamespace=pg_my_temp_schema() ORDER BY c.relname,a.attname LIMIT 4) x),'policies',(SELECT json_agg(x) FROM (SELECT 'public.'||c.relname AS relation,p.polname,pg_get_expr(p.polqual,p.polrelid,false) AS using_expr,pg_get_expr(p.polwithcheck,p.polrelid,false) AS check_expr FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid WHERE c.relnamespace=pg_my_temp_schema() ORDER BY c.relname,p.polname LIMIT 33) x),'predicates',(SELECT json_agg(x) FROM (SELECT 'public.'||c.relname AS relation,pg_get_expr(i.indpred,i.indrelid,false) AS expression FROM pg_index i JOIN pg_class c ON c.oid=i.indrelid WHERE c.relnamespace=pg_my_temp_schema() AND i.indpred IS NOT NULL LIMIT 2) x)); ROLLBACK;